'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { Copy, Check, KeyRound } from 'lucide-react';
import { cn } from '@/lib/utils';
import { browserApiUrl } from '@/lib/config';

/**
 * Issue somebody a new password.
 *
 * The recovery path for a person who has forgotten theirs, or whose account is
 * locked out after too many failed attempts.
 *
 * The password is generated by the API rather than typed here. Somebody who
 * has forgotten their password is usually handed a new one over a phone call,
 * and "password123" is exactly what a hurried administrator types at that
 * moment. Generating it makes the strength of it independent of how rushed
 * the person handing it over is.
 *
 * The generated password is shown exactly once. It is not stored in plain
 * text anywhere and it is not in the audit log — the log records that a reset
 * happened, not what the new password was. If it is lost, reset again.
 */
export function ResetPasswordDialog({ user, triggerLabel = 'Reset password' }) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState(null);
  const [issued, setIssued] = useState(null);
  const [copied, setCopied] = useState(false);

  function close() {
    setOpen(false);
    setError(null);
    setIssued(null);
    setCopied(false);
  }

  async function handleReset() {
    setPending(true);
    setError(null);

    try {
      const response = await fetch(browserApiUrl(`/api/users/${user.id}/reset-password`), {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      });

      const data = await response.json().catch(() => ({}));

      if (!response.ok) {
        setError(data.error?.message || 'That password could not be reset.');
        setPending(false);
        return;
      }

      setIssued(data.data?.temporaryPassword || null);
      setPending(false);
      router.refresh();
    } catch {
      setError('The management service did not respond. Please try again.');
      setPending(false);
    }
  }

  async function copyPassword() {
    if (!issued) return;

    try {
      await navigator.clipboard.writeText(issued);
      setCopied(true);
    } catch {
      // Clipboard access can be refused. The password is on screen either way,
      // so this is a convenience, not a requirement.
    }
  }

  return (
    <>
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="inline-flex h-9 items-center rounded-md border border-line px-3 text-sm font-semibold text-ink-soft transition-colors hover:bg-surface-muted"
      >
        {triggerLabel}
      </button>

      {open ? (
        <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto p-4 sm:items-center">
          <div className="fixed inset-0 bg-ink/50" onClick={close} aria-hidden="true" />

          <div
            role="dialog"
            aria-modal="true"
            aria-labelledby="reset-password-title"
            className="relative my-auto w-full max-w-md rounded-lg border border-line bg-surface shadow-xl"
          >
            <header className="border-b border-line px-6 py-4">
              <h2 id="reset-password-title" className="text-lg font-semibold">
                Reset password for {user.email}
              </h2>
            </header>

            <div className="flex flex-col gap-4 px-6 py-5">
              {error ? (
                <p
                  role="alert"
                  className="rounded-md border border-danger/30 bg-danger-bg p-3 text-sm text-danger"
                >
                  {error}
                </p>
              ) : null}

              {issued ? (
                <>
                  <div className="rounded-md border border-success/30 bg-success-bg p-3 text-sm text-success">
                    <p className="font-semibold">Password issued</p>
                    <p className="mt-1">
                      Every session on this account has been signed out, and any lockout has
                      been cleared.
                    </p>
                  </div>

                  <div className="flex flex-col gap-2">
                    <label className="text-sm font-medium text-ink-soft">
                      Temporary password
                    </label>
                    <div className="flex items-center gap-2">
                      <code className="flex-1 select-all rounded-md border border-line bg-surface-muted px-3 py-2 font-mono text-sm">
                        {issued}
                      </code>
                      <button
                        type="button"
                        onClick={copyPassword}
                        className="inline-flex h-10 items-center gap-1.5 rounded-md border border-line px-3 text-sm font-medium text-ink-soft hover:bg-surface-muted"
                      >
                        {copied ? (
                          <Check className="size-4" aria-hidden="true" />
                        ) : (
                          <Copy className="size-4" aria-hidden="true" />
                        )}
                        {copied ? 'Copied' : 'Copy'}
                      </button>
                    </div>
                    <p className="text-xs text-ink-subtle">
                      This is shown once. Pass it on securely, and ask them to change it
                      when they sign in.
                    </p>
                  </div>
                </>
              ) : (
                <>
                  <p className="text-sm text-ink-muted">
                    A strong temporary password will be generated and shown to you once.
                  </p>
                  <ul className="flex flex-col gap-1.5 text-xs text-ink-subtle">
                    <li>Every session on the account is signed out.</li>
                    <li>Any lockout from failed sign-in attempts is cleared.</li>
                    <li>
                      The account must choose a password of its own at the next sign-in.
                    </li>
                  </ul>
                </>
              )}
            </div>

            <footer className="flex justify-end gap-3 border-t border-line px-6 py-4">
              <button
                type="button"
                onClick={close}
                className="h-9 rounded-md border border-line px-4 text-sm font-medium text-ink-soft hover:bg-surface-muted"
              >
                {issued ? 'Done' : 'Cancel'}
              </button>

              {!issued ? (
                <button
                  type="button"
                  onClick={handleReset}
                  disabled={pending}
                  className={cn(
                    'inline-flex h-9 items-center gap-2 rounded-md bg-brand-500 px-4 text-sm',
                    'font-semibold text-white hover:bg-brand-600 disabled:opacity-60',
                  )}
                >
                  <KeyRound className="size-4" aria-hidden="true" />
                  {pending ? 'Issuing…' : 'Issue password'}
                </button>
              ) : null}
            </footer>
          </div>
        </div>
      ) : null}
    </>
  );
}

export default ResetPasswordDialog;
